def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))
    # Extend each interior marker in its row toward a boundary streak. Markers
    # are replaced by 4; the intervening background becomes the marker color.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color == bg:
                continue
            out[r][c] = 4
            if any(grid[rr][0] != bg for rr in range(h)):
                for cc in range(1, c):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
            elif any(grid[rr][w - 1] != bg for rr in range(h)):
                for cc in range(c + 1, w - 1):
                    if grid[r][cc] == bg:
                        out[r][cc] = color
    return out

