def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(row.count(v) for row in grid))
    out=[row[:] for row in grid]
    # Find two matching colored bars on opposite edges; they delimit the
    # rectangular region to fill. Internal marker pixels create holes (4s).
    bars=[]
    for r in (0,h-1):
        cs=[c for c in range(w) if grid[r][c]!=bg]
        if cs: bars.append((r,min(cs),max(cs),grid[r][cs[0]]))
    if len(bars)==2:
        r0,l0,r0hi,color=bars[0]
        r1,l1,r1hi,color2=bars[1]
        if color==color2:
            left=max(l0,l1); right=min(r0hi,r1hi)
            # fill from the two bars inward, between their shared columns
            for rr in range(h):
                for cc in range(left,right+1):
                    if grid[rr][cc]==bg: out[rr][cc]=color
            for rr in range(1,h-1):
                for cc in range(1,w-1):
                    if grid[rr][cc]!=bg and grid[rr][cc]!=color: out[rr][cc]=4
    return out
PY
